"""Kickstart 生成服务"""
import re
import logging
from typing import Optional, List
from backend.models.osdeploy import KickStartFileStatus, RepoStatus
from backend.models.host import Host

logger = logging.getLogger(__name__)


class KickstartService:
    """Kickstart 模板渲染与生成服务"""

